function drawMoltresFlamePhoenix(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.5;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 3.5;

  const wingFlap = Math.sin(t * 3.2) * 6.0;
  const flameWiggle = Math.sin(t * 7.0) * 2.5;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 44, 28 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Đuôi lửa
  ctx.fillStyle = '#ef4444';
  ctx.beginPath(); ctx.moveTo(-8, by + 18); ctx.lineTo(-28 + flameWiggle, by + 32); ctx.lineTo(0, by + 24); ctx.fill();
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.moveTo(-6, by + 18); ctx.lineTo(-24 + flameWiggle, by + 30); ctx.lineTo(0, by + 22); ctx.fill();

  // 3. Thân
  ctx.fillStyle = '#fde047';
  ctx.beginPath(); ctx.ellipse(0, by + 12, 14 * sX, 18 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // 4. Cánh lửa trái & phải
  const wly = by + wingFlap;
  ctx.fillStyle = '#ef4444';
  ctx.beginPath(); ctx.moveTo(-10, by + 6); ctx.lineTo(-40, wly - 16); ctx.lineTo(-18, by + 18); ctx.fill();
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.moveTo(-12, by + 8); ctx.lineTo(-36, wly - 14); ctx.lineTo(-20, by + 16); ctx.fill();
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.moveTo(-14, by + 10); ctx.lineTo(-30, wly - 10); ctx.lineTo(-20, by + 14); ctx.fill();

  const wry = by - wingFlap;
  ctx.fillStyle = '#ef4444';
  ctx.beginPath(); ctx.moveTo(10, by + 6); ctx.lineTo(40, wry - 16); ctx.lineTo(18, by + 18); ctx.fill();
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.moveTo(12, by + 8); ctx.lineTo(36, wry - 14); ctx.lineTo(20, by + 16); ctx.fill();
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.moveTo(14, by + 10); ctx.lineTo(30, wry - 10); ctx.lineTo(20, by + 14); ctx.fill();

  // 5. Cổ & Đầu
  ctx.fillStyle = '#fde047';
  ctx.beginPath(); ctx.roundRect(-4, by - 6, 8, 14, 3); ctx.fill();
  ctx.beginPath(); ctx.arc(0, by - 12, 10, 0, Math.PI * 2); ctx.fill();

  // 6. Mào lửa
  ctx.fillStyle = '#ef4444';
  ctx.beginPath(); ctx.moveTo(-4, by - 18); ctx.lineTo(flameWiggle, by - 36); ctx.lineTo(8, by - 16); ctx.fill();
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.moveTo(-2, by - 18); ctx.lineTo(flameWiggle, by - 32); ctx.lineTo(6, by - 16); ctx.fill();
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.moveTo(0,  by - 18); ctx.lineTo(flameWiggle, by - 26); ctx.lineTo(4, by - 16); ctx.fill();

  // 7. Mỏ nhọn
  ctx.fillStyle = '#e2e8f0';
  ctx.beginPath(); ctx.moveTo(-4, by - 12); ctx.lineTo(-18, by - 8); ctx.lineTo(-4, by - 6); ctx.fill();

  // 8. Mắt
  if (!blink) {
    ctx.fillStyle = '#1e293b';
    ctx.beginPath(); ctx.arc(2, by - 12, 3, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#fef08a';
    ctx.beginPath(); ctx.arc(1, by - 13, 1, 0, Math.PI * 2); ctx.fill();
  } else {
    ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(0, by - 12); ctx.lineTo(4, by - 12); ctx.stroke();
  }

  // 9. Chân
  ctx.fillStyle = '#e2e8f0';
  ctx.beginPath(); ctx.roundRect(-6, by + 28, 4, 10, 2); ctx.fill();
  ctx.beginPath(); ctx.roundRect(2,  by + 28, 4, 10, 2); ctx.fill();

  ctx.restore();
}
